export interface Use extends langium.AstNode {
    readonly $container: Policy;
    readonly $type: 'Use';
    entries: Array<UsePack>;
}

export const Use = {
    $type: 'Use',
    entries: 'entries'
} as const;

export function isUse(item: unknown): item is Use {
    return reflection.isInstance(item, Use.$type);
}

